CREATE DATABASE IF NOT EXISTS adaptivelearn CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE adaptivelearn;
CREATE TABLE users (id CHAR(36) PRIMARY KEY, full_name VARCHAR(120) NOT NULL, email VARCHAR(255) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, role ENUM('student','trainer') NOT NULL DEFAULT 'student', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX idx_users_role(role));
CREATE TABLE courses (id CHAR(36) PRIMARY KEY, title VARCHAR(160) NOT NULL, description TEXT NOT NULL, created_by CHAR(36) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY uq_course_title(title), CONSTRAINT fk_courses_creator FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE RESTRICT);
CREATE TABLE concepts (id CHAR(36) PRIMARY KEY, course_id CHAR(36) NOT NULL, title VARCHAR(160) NOT NULL, description TEXT NOT NULL, learning_objectives JSON NOT NULL, category VARCHAR(80) NOT NULL DEFAULT 'Core Java', difficulty ENUM('Beginner','Intermediate','Advanced') NOT NULL, estimated_minutes INT UNSIGNED NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, UNIQUE KEY uq_concept_course_title(course_id,title), INDEX idx_concepts_course(course_id), CONSTRAINT fk_concepts_course FOREIGN KEY(course_id) REFERENCES courses(id) ON DELETE CASCADE);
CREATE TABLE concept_prerequisites (concept_id CHAR(36) NOT NULL, prerequisite_concept_id CHAR(36) NOT NULL, PRIMARY KEY(concept_id, prerequisite_concept_id), CONSTRAINT chk_not_self CHECK (concept_id <> prerequisite_concept_id), CONSTRAINT fk_cp_concept FOREIGN KEY(concept_id) REFERENCES concepts(id) ON DELETE CASCADE, CONSTRAINT fk_cp_prereq FOREIGN KEY(prerequisite_concept_id) REFERENCES concepts(id) ON DELETE RESTRICT);
CREATE TABLE student_concept_progress (id CHAR(36) PRIMARY KEY, student_id CHAR(36) NOT NULL, concept_id CHAR(36) NOT NULL, completion_status ENUM('not_started','in_progress','completed') NOT NULL DEFAULT 'not_started', completion_source ENUM('self_reported','assessment') NOT NULL DEFAULT 'self_reported', updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, UNIQUE KEY uq_student_concept(student_id,concept_id), INDEX idx_progress_student(student_id), CONSTRAINT fk_progress_student FOREIGN KEY(student_id) REFERENCES users(id) ON DELETE CASCADE, CONSTRAINT fk_progress_concept FOREIGN KEY(concept_id) REFERENCES concepts(id) ON DELETE CASCADE);
CREATE TABLE refresh_sessions (id CHAR(36) PRIMARY KEY, user_id CHAR(36) NOT NULL, token_hash CHAR(64) NOT NULL UNIQUE, expires_at DATETIME NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX idx_refresh_user(user_id), CONSTRAINT fk_session_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
